"""
    Combine each two chromosomes in population by using single point crossover.
    """
def single_point_crossover(population: Any, single_point_info: Any) -> object {
    crossover_points = [
        int(p)
        for p in single_point_info.split("|")
        if (p != '')
    ];
    new_population = [];
    for i in range(0, (len(population) - 1), 2) {
        candidate1 = population[i];
        candidate2 = population[(i + 1)];
        crossover_point = crossover_points[int((i / 2))];
        offspring1 = candidate2[0:crossover_point] + candidate1[crossover_point:];
        offspring2 = candidate1[0:crossover_point] + candidate2[crossover_point:];
        new_population.append(offspring1);
        new_population.append(offspring2);
    }
    if ((len(population) % 2) == 1) {
        new_population.append(population[(len(population) - 1)]);
    }
    return new_population;
}

"""
    mode 0: splits an ascii string and adds elements to a list.
    mode 1: converts list elements to ascii characters and joins them.
    """
def str_list(data_in: Any, mode: Any = 0) -> object {
    if (mode == 0) {
        data_out = [];
        for i in range(len(data_in)) {
            data_out.append(ord(data_in[i]));
        }
        return data_out;
    }
    data_out = '';
    for i in range(16) {
        data_out += chr(data_in[i]);
    }
    return data_out;
}

"""
    line y = ax + b. returns a,b

    """
def get_line_cf(x0: Any, y0: Any, x1: Any, y1: Any) -> object {
    sameX = abs((x1 - x0)) < 1e-06;
    sameY = abs((y1 - y0)) < 1e-06;
    if (sameX and sameY) {
        return (None, None);
    }
    if sameX {
        a = None;
        b = x0;
    } elif sameY {
        a = 0;
        b = y0;
    } else {
        a = (y1 - y0) / (x1 - x0);
        b = ((y0 * x1) - (x0 * y1)) / (x1 - x0);
    }
    return (a, b);
}
